package com.assetwright.app.mini

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.nio.file.Files
import java.nio.file.Path
import java.security.MessageDigest
import kotlin.math.roundToInt

/**
 * Independent second-generation strength calibration source lab.
 * All training/evaluation GLBs are newly generated by OWN Kotlin engine;
 * previously inspected bdhold families are not re-used.
 */
class DinoContinualGeometryBatchTest {
    private data class Dims(val length:Float,val width:Float,val height:Float)
    private data class Family(val id:String,val dims:Dims)

    private val training=(1..12).map { i ->
        Family("bc_train"+i.toString().padStart(2,'0'), Dims(
            2.69f+i*.247f+(i%3)*.11f,
            1.31f+(i%4)*.345f+(i/4)*.092f,
            .99f+(i%5)*.245f+(i/5)*.097f
        ))
    }
    private val development=listOf(
        Family("bc_dev01",Dims(3.47f,2.22f,1.62f)),
        Family("bc_dev02",Dims(5.39f,2.56f,2.43f)),
        Family("bc_dev03",Dims(4.59f,1.72f,2.39f)),
        Family("bc_dev04",Dims(6.46f,2.66f,1.34f))
    )
    private val validation=listOf(
        Family("bc_blind01",Dims(3.64f,2.39f,1.87f)),
        Family("bc_blind02",Dims(5.84f,2.18f,2.09f)),
        Family("bc_blind03",Dims(4.92f,2.99f,1.21f)),
        Family("bc_blind04",Dims(6.51f,2.44f,1.81f))
    )
    private val levels=mapOf(
        "train" to listOf(.03f,.18f,.36f,.52f,.68f,.83f,.97f),
        "development" to listOf(.10f,.40f,.60f,.90f),
        "validation" to listOf(.07f,.27f,.73f,.95f)
    )
    private fun digest(bytes:ByteArray):String =
        MessageDigest.getInstance("SHA-256").digest(bytes).joinToString("") {
            "%02x".format(it.toInt() and 255)
        }

    private fun write(root:Path,split:String,family:Family,
                      op:AdvancedFormOperation,strength:Float,baseline:Boolean) {
        val id=if (baseline) "baseline" else
            op.name.lowercase()+"__s"+(strength*1000).roundToInt().toString().padStart(3,'0')
        val stem=split+"__"+family.id+"__"+id
        val d=family.dims
        val mesh=AdvancedFormLab.generate(AdvancedFormSpec(
            op,d.length,d.width,d.height,strength))
        assertTrue("Original native triangle limit",mesh.indices.size/3 in 900..3000)
        val carrier=VehicleSpec("Original continuing skill school",4f,2f,1.4f,
            1.7f,.5f,1f,"Mobile","Kotlin-only research generated GLB")
        val bytes=GlbWriter.encode(GeneratedAsset(carrier,listOf(mesh)))
        val sha=digest(bytes)
        Files.write(root.resolve(stem+".glb"),bytes)
        val record="{\"schema\":\"assetwright-native-before-after-source-v1\","+
            "\"original_engine\":\"AssetWright-AdvancedFormLab\","+
            "\"case\":\""+stem+"\","+
            "\"split\":\""+split+"\","+
            "\"family\":\""+family.id+"\","+
            "\"baseline\":"+baseline+","+
            "\"operation\":\""+(if(baseline) "BASELINE" else op.name)+"\","+
            "\"strength\":"+strength+","+
            "\"length\":"+d.length+","+
            "\"width\":"+d.width+","+
            "\"height\":"+d.height+","+
            "\"source_glb_sha256\":\""+sha+"\"}"
        Files.write(root.resolve(stem+".json"),record.toByteArray(Charsets.UTF_8))
    }

    @Test
    fun exportFreshContinualGeometryFamilies() {
        val directory=System.getenv("ASSETWRIGHT_CONTINUAL_SOURCE")
            ?.takeIf { it.isNotBlank() } ?: return
        val root=Path.of(directory)
        Files.createDirectories(root)
        var changed=0
        var baselines=0
        for((phase,families) in listOf(
            Pair("train",training),
            Pair("development",development),
            Pair("validation",validation)
        )) {
            for(family in families) {
                write(root,phase,family,AdvancedFormOperation.SECTION_LOFT,0f,true)
                baselines++
                for(op in AdvancedFormOperation.values()) {
                    for(strength in levels.getValue(phase)) {
                        write(root,phase,family,op,strength,false)
                        changed++
                    }
                }
            }
        }
        assertEquals(20,baselines)
        assertEquals(696,changed)
        assertEquals(716,Files.list(root).use { stream ->
            stream.filter { it.fileName.toString().endsWith(".glb") }.count().toInt()
        })
    }
}
